// ===== Pin Definitions =====
#define MOTOR_IN1 12   // Motor direction pin 1
#define MOTOR_IN2 25   // Motor direction pin 2

#define BTN_DOWN 10    // Button for DOWN (anti-clockwise)
#define BTN_UP   11    // Button for UP (clockwise)

void setup() {
  Serial.begin(115200);

  pinMode(MOTOR_IN1, OUTPUT);
  pinMode(MOTOR_IN2, OUTPUT);

  pinMode(BTN_DOWN, INPUT_PULLUP);
  pinMode(BTN_UP, INPUT_PULLUP);

  // Motor OFF initially
  digitalWrite(MOTOR_IN1, LOW);
  digitalWrite(MOTOR_IN2, LOW);
}

// ===== Motor Control Functions =====
void motorStop() {
  digitalWrite(MOTOR_IN1, LOW);
  digitalWrite(MOTOR_IN2, LOW);
}

void motorClockwise() {       // UP
  digitalWrite(MOTOR_IN1, HIGH);
  digitalWrite(MOTOR_IN2, LOW);
}

void motorAntiClockwise() {   // DOWN
  digitalWrite(MOTOR_IN1, LOW);
  digitalWrite(MOTOR_IN2, HIGH);
}

void loop() {
  bool downPressed = (digitalRead(BTN_DOWN) == LOW);
  bool upPressed   = (digitalRead(BTN_UP) == LOW);

  if (upPressed && !downPressed) {
    motorClockwise();
    Serial.println("Motor: UP (Clockwise)");
  }
  else if (downPressed && !upPressed) {
    motorAntiClockwise();
    Serial.println("Motor: DOWN (Anti-clockwise)");
  }
  else {
    motorStop();  // no button or both buttons
  }

  delay(50); // small debounce / CPU relief
}
